create table poet
(
    id               bigint auto_increment comment '诗人ID'
        primary key,
    name             varchar(100)                       not null comment '诗人名称',
    dynasty_id       bigint                             null comment '所属朝代ID',
    birth_year       int                                null comment '出生年份',
    death_year       int                                null comment '逝世年份',
    birthplace       varchar(200)                       null comment '出生地',
    biography        text                               null comment '诗人简介',
    avatar_url       text                               null comment '头像图片URL列表(JSON数组)',
    avatar_anime_url text                               null comment '动漫风格头像URL列表(JSON数组)',
    style            varchar(200)                       null comment '诗词风格',
    created_at       datetime default CURRENT_TIMESTAMP null comment '创建时间',
    updated_at       datetime default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间',
    constraint poet_ibfk_1
        foreign key (dynasty_id) references dynasty (id)
)
    comment '诗人表' charset = utf8mb4;

create index dynasty_id
    on poet (dynasty_id);

